class Solution {
public:
    int maximizeSweetness(std::vector<int>& sweetness, int k) {
        auto canDivide = [&](int target) -> bool {
            int pieces = 0, cur = 0;
            for (int s : sweetness) {
                cur += s;
                if (cur >= target) {
                    pieces++;
                    cur = 0;
                }
            }
            return pieces >= k + 1;
        };

        long long total = 0;
        for (int s : sweetness) total += s;
        int low = 1, high = total / (k + 1), ans = 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canDivide(mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int maximizeSweetness(int[] sweetness, int k) {
        long total = 0;
        for (int s : sweetness) total += s;
        int low = 1, high = (int) (total / (k + 1)), ans = 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int pieces = 0, cur = 0;
            for (int s : sweetness) {
                cur += s;
                if (cur >= mid) {
                    pieces++;
                    cur = 0;
                }
            }
            if (pieces >= k + 1) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

var maximizeSweetness = function(sweetness, k) {
    let total = 0;
    for (const s of sweetness) total += s;
    let low = 1, high = Math.floor(total / (k + 1)), ans = 1;
    while (low <= high) {
        const mid = (low + high) >> 1;
        let pieces = 0, cur = 0;
        for (const s of sweetness) {
            cur += s;
            if (cur >= mid) {
                pieces++;
                cur = 0;
            }
        }
        if (pieces >= k + 1) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
};
